insert into public.questoes (id, rank, topic, origin, file_source, stem, options, answer, year, qnum, score, band, resolution, summary) values
($qq$3114937$qq$, 301, $qq$AFO, Direito Financeiro e Contabilidade Pública - Temas Mesclados sobre a LRF$qq$, $qq$FAFIPA - PJur (Pref Contenda)/Pref Contenda/2024$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Em relação às disposições que constam expressamente da Lei de Responsabilidade Fiscal (Lei Complementar nº 101/2000), assinale a alternativa INCORRETA.$qq$, $qq$[["A", "A Lei de Responsabilidade Fiscal determina que é vedado ao ente da Federação realizar operação de crédito que exceda o montante das despesas de capital, salvo em casos específicos autorizados pelo Senado Federal."], ["B", "A Lei de Responsabilidade Fiscal permite a contratação de operação de crédito por antecipação de receita, mesmo sem a existência de disponibilidade de caixa, desde que destinada a despesas correntes imprevistas ou urgentes.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                              15/57"], ["C", "A Lei de Responsabilidade Fiscal estabelece que a despesa com pessoal não poderá exceder a 60% da receita corrente líquida nos Estados e Municípios."], ["D", "A Lei de Responsabilidade Fiscal prevê que a transparência na gestão fiscal será assegurada mediante a participação popular e a realização de audiências públicas durante os processos de elaboração e discussão dos planos, leis de diretrizes orçamentárias e orçamentos."], ["E", "A Lei de Responsabilidade Fiscal impõe limites de endividamento para os entes da Federação, com base em percentuais da receita corrente líquida, estabelecendo mecanismos de controle e fiscalização."]]$qq$::jsonb, $qq$B$qq$, 2024, 254, 1079, $qq$A$qq$, $qq${"what": "Identificação da alternativa incorreta sobre a LRF.", "rule": "A LRF veda operação de crédito em desacordo com as regras fiscais e disciplina a ARO, pessoal, transparência e endividamento. A operação de crédito por antecipação de receita orçamentária (ARO) tem requisitos específicos e não pode ser usada livremente para financiar despesa corrente imprevista.", "steps": ["A alternativa B afirma que ARO pode ser contratada sem disponibilidade de caixa e para despesas correntes imprevistas ou urgentes.", "Essa formulação não corresponde ao regime da LRF para ARO.", "As demais alternativas descrevem, em linhas gerais, regras expressas da LRF."], "calc": "Não há cálculo.", "correct": "B — é a INCORRETA.", "wrong": "A relaciona-se à regra de ouro prevista no art. 12, §2º; C reproduz o limite global de pessoal dos Estados e Municípios; D trata da transparência; E trata dos limites de endividamento.", "basis": "Lei Complementar nº 101/2000, especialmente arts. 9º, 12, 32–38 e 48.", "trap": "Não confundir ARO com empréstimo comum nem imaginar que urgência da despesa elimina os requisitos legais da ARO."}$qq$::jsonb, $qq$Em relação às disposições que constam expressamente da Lei de Responsabilidade Fiscal (Lei Complementar nº 101/2000), assinale a alternativa INCORRETA.$qq$),
($qq$2715416$qq$, 302, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (CM Nova Fátima (PR))/CM Nova Fátima (PR)/2023$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                           42/54 152) Nos termos da Lei de Responsabilidade Fiscal - Lei Complementar nº 101/2000 -, o percentual máximo da Receita Corrente Líquida Municipal que a Câmara de Vereadores poderá gastar com Despesas de Pessoal, em cada período de apuração, é de:$qq$, $qq$[["A", "7%."], ["B", "6%."], ["C", "4%."], ["D", "5%."], ["E", "8%."]]$qq$::jsonb, $qq$B$qq$, 2023, null, 1078, $qq$A$qq$, $qq${"what": "Limite de pessoal do Poder Legislativo municipal.", "rule": "No âmbito municipal, o limite global de despesa com pessoal é 60% da RCL; desse total, cabem 6% ao Legislativo, incluído o Tribunal de Contas do Município, quando houver, e 54% ao Executivo.", "steps": ["Partir do limite global municipal de 60% da RCL.", "Aplicar a repartição do art. 20, III, da LRF.", "Para o Legislativo municipal, o limite é 6%."], "calc": "Limite da Câmara = 6% da Receita Corrente Líquida.", "correct": "B — 6%.", "wrong": "7%, 4%, 5% e 8% não correspondem ao limite do Legislativo municipal na LRF.", "basis": "Lei Complementar nº 101/2000, arts. 19, III, e 20, III, “a”.", "trap": "A banca pode apresentar 60% — que é o limite global municipal — como se fosse o limite da Câmara."}$qq$::jsonb, $qq$w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                           42/54 152) Nos termos da Lei de Responsabilidade Fiscal - Lei Complementar nº 101/2000 -, o percentual máximo da Receita Corrente Líquida Municipal que a Câmara de Vereadores poderá gastar com Despesas de Pes…$qq$),
($qq$2746553$qq$, 303, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (CM A Chateaubriand)/CM A Chateaubriand/2023$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Conforme estabelece a Lei Complementar nº 101/2000 - Lei de Responsabilidade Fiscal -, nos municípios, a despesa total com pessoal em cada período de apuração não poderá exceder os percentuais da receita corrente líquida em:$qq$, $qq$[["A", "30% (trinta por cento)."], ["B", "40% (quarenta por cento)."], ["C", "60% (sessenta por cento)."], ["D", "50% (cinquenta por cento)."]]$qq$::jsonb, $qq$C$qq$, 2023, 153, 1078, $qq$A$qq$, $qq${"what": "Limite global de despesa com pessoal dos Municípios.", "rule": "A despesa total com pessoal, em cada período de apuração, não pode exceder 60% da RCL nos Municípios.", "steps": ["Identificar o ente: Município.", "Aplicar o art. 19, III, da LRF.", "O limite global é 60% da RCL."], "calc": "Limite = 60% da RCL.", "correct": "C — 60%.", "wrong": "30%, 40% e 50% não são o limite global municipal previsto no art. 19, III.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Memorize separado: limite global municipal 60%; dentro dele, Executivo 54% e Legislativo 6%."}$qq$::jsonb, $qq$Conforme estabelece a Lei Complementar nº 101/2000 - Lei de Responsabilidade Fiscal -, nos municípios, a despesa total com pessoal em cada período de apuração não poderá exceder os percentuais da receita corrente líquida em:$qq$),
($qq$2416273$qq$, 304, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont (FAZPREV)/FAZPREV/2023$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 210) O objetivo da elaboração e divulgação da informação contábil é fornecer informação para fins de prestação de contas e responsabilização (accountability) e tomada de decisão. As características qualitativas são atributos que tornam a informação útil para os usuários e dão suporte ao cumprimento dos objetivos da informação contábil. De acordo com o Manual de Contabilidade Aplicado ao Setor Público (MCASP), assinale a opção que defina a característica "verificabilidade":$qq$, $qq$[["A", "Verificabilidade é a qualidade da informação que possibilita aos usuários identificar semelhanças e diferenças entre dois conjuntos de fenômenos."], ["B", "Verificabilidade evidencia que a qualidade das informações financeiras e não financeiras são relevantes caso sejam capazes de influenciar significativamente o cumprimento dos objetivos da elaboração e da divulgação da informação contábil."], ["C", "Verificabilidade é a qualidade da informação que permite que os usuários compreendam o seu significado."], ["D", "Verificabilidade é a qualidade da informação que ajuda a assegurar aos usuários que a informação contida nas demonstrações contábeis representa fielmente os fenômenos econômicos ou de outra natureza que se propõe a representar."], ["E", "Verificabilidade significa ter informação disponível para os usuários antes que ela perca a sua capacidade de ser útil para fins do objetivo da elaboração e divulgação da informação contábil."]]$qq$::jsonb, $qq$D$qq$, 2023, null, 1078, $qq$A$qq$, $qq${"what": "Característica qualitativa da verificabilidade na informação contábil pública.", "rule": "Verificabilidade ajuda a assegurar aos usuários que a informação representa fielmente os fenômenos econômicos ou de outra natureza que se propõe a representar.", "steps": ["Comparar as alternativas com as definições das características qualitativas.", "A alternativa D descreve a verificabilidade.", "As demais descrevem comparabilidade, relevância, compreensibilidade e tempestividade."], "calc": "Não há cálculo.", "correct": "D.", "wrong": "A é comparabilidade; B é relevância; C é compreensibilidade; E é tempestividade.", "basis": "MCASP/NBC TSP Estrutura Conceitual — características qualitativas da informação contábil.", "trap": "Não confundir verificabilidade com representação fidedigna: a primeira ajuda a assegurar que a representação fidedigna pode ser sustentada/verificada."}$qq$::jsonb, $qq$caps. 1 a 4) 210) O objetivo da elaboração e divulgação da informação contábil é fornecer informação para fins de prestação de contas e responsabilização (accountability) e tomada de decisão. As características qualitativas são atributos que tornam a informação útil para os usuários e dão suporte ao cumprimento dos objetivos da informação contábil. De acordo…$qq$),
($qq$2153554$qq$, 305, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (CISA AMERIOS)/CISA AMERIOS/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$A despesa total com pessoal nos municípios, em cada período de apuração, em conformidade com a Lei de Responsabilidade Fiscal (Lei Complementar 101 de 04 de maio de 2000), não poderá exceder os percentuais da receita corrente líquida em:$qq$, $qq$[["A", "70%."], ["B", "30%."], ["C", "50%."], ["D", "40%."], ["E", "60%."]]$qq$::jsonb, $qq$E$qq$, 2022, 154, 1078, $qq$A$qq$, $qq${"what": "Limite global de pessoal dos Municípios.", "rule": "O limite global de despesa total com pessoal dos Municípios é de 60% da Receita Corrente Líquida.", "steps": ["Identificar o ente municipal.", "Aplicar o art. 19, III, da LRF.", "Selecionar 60%."], "calc": "60% da RCL.", "correct": "E — 60%.", "wrong": "70%, 30%, 50% e 40% não são o limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Questão direta de memorização; cuidado para não trocar o limite global pelo limite de um Poder."}$qq$::jsonb, $qq$A despesa total com pessoal nos municípios, em cada período de apuração, em conformidade com a Lei de Responsabilidade Fiscal (Lei Complementar 101 de 04 de maio de 2000), não poderá exceder os percentuais da receita corrente líquida em:$qq$),
($qq$2431292$qq$, 306, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (União Oeste) /Pref União do Oeste/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$De acordo com a Lei de Responsabilidade Fiscal (Lei Complementar nº 101/2000), a despesa total com pessoal nos municípios, em cada período de apuração, não deve exceder a receita corrente líquida em:$qq$, $qq$[["A", "60%."], ["B", "15%."], ["C", "30%."], ["D", "27,50%."]]$qq$::jsonb, $qq$A$qq$, 2022, 155, 1078, $qq$A$qq$, $qq${"what": "Limite global de pessoal dos Municípios.", "rule": "Municípios: 60% da RCL para despesa total com pessoal.", "steps": ["Identificar o Município.", "Aplicar o limite do art. 19, III.", "Resultado: 60%."], "calc": "60% da RCL.", "correct": "A — 60%.", "wrong": "15%, 30% e 27,50% não são o limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "A banca troca frequentemente o 60% global pelos 54% do Executivo ou 6% do Legislativo."}$qq$::jsonb, $qq$De acordo com a Lei de Responsabilidade Fiscal (Lei Complementar nº 101/2000), a despesa total com pessoal nos municípios, em cada período de apuração, não deve exceder a receita corrente líquida em:$qq$),
($qq$2156862$qq$, 307, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - AFis (Pref Ivinhema)/Pref Ivinhema/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 211) De acordo com a NBC TSP - Estrutura Conceitual para Elaboração e Divulgação de Informação Contábil de Propósito Geral pelas Entidades do Setor Público, avalie as afirmativas apresentadas a seguir sobre as características qualitativas da informação incluídas no Relatório Contábil de Propósito Geral das Entidades do Setor Público  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                                   3/57 (RCPG): I.É a qualidade da informação que ajuda a assegurar aos usuários que a informação contida no Relatório Contábil de Propósito Geral das Entidades do Setor Público (RCPG) representa fielmente os fenômenos econômicos ou de outra natureza que se propõe a representar. II.É a qualidade da informação que possibilita aos usuários identificar semelhanças e diferenças entre dois conjuntos de fenômenos, o que representa a qualidade da relação entre dois ou mais itens de informação. III.É a qualidade da informação que permite que os usuários entendam o seu significado. IV.Para ser útil como informação contábil, a informação deve corresponder exatamente os fenômenos econômicos e outros que se pretenda representar, sendo alcançada quando a informação reportada é completa, neutra e livre de erro material. V.Significa ter informação disponível para os usuários antes que ela perca a sua capacidade de ser útil para fins de prestação de contas e responsabilização (accountability) e tomada de decisão, sendo que sua ausência pode tornar a informação menos útil. VI.As informações financeiras e não financeiras são capazes de influenciar significativamente o cumprimento dos objetivos da elaboração e da divulgação da informação contábil, quando têm valor confirmatório, preditivo ou ambos. Assinale a alternativa que relaciona CORRETAMENTE o conceito com as características da informação contábil:$qq$, $qq$[["A", "I - representação fidedigna; II - comparabilidade; III - compreensibilidade; IV - verificabilidade; V - tempestividade; VI - relevância."], ["B", "I - representação fidedigna; II - relevância; III - compreensibilidade; IV - verificabilidade; V - tempestividade; VI - comparabilidade."], ["C", "I - verificabilidade; II - comparabilidade; III - compreensibilidade; IV - representação fidedigna; V - tempestividade; VI - relevância."], ["D", "I - verificabilidade; II - relevância; III - compreensibilidade; IV - representação fidedigna; V - tempestividade; VI - comparabilidade."], ["E", "I - verificabilidade; II - comparabilidade; III - compreensibilidade; IV - representação fidedigna; V - relevância; VI - tempestividade."]]$qq$::jsonb, $qq$C$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Identificação das características qualitativas da informação contábil.", "rule": "I descreve representação fidedigna; II, comparabilidade; III, compreensibilidade; IV, representação fidedigna; V, tempestividade; VI, relevância. A questão, contudo, usa IV como definição de representação fidedigna e a alternativa correta é a que organiza as correspondências conforme o texto.", "steps": ["I: “representa fielmente” → representação fidedigna.", "II: identificar semelhanças e diferenças → comparabilidade.", "III: entender o significado → compreensibilidade.", "IV: completa, neutra e livre de erro material → representação fidedigna.", "V: informação disponível antes de perder utilidade → tempestividade.", "VI: valor confirmatório, preditivo ou ambos → relevância."], "calc": "Não há cálculo.", "correct": "C — conforme o gabarito registrado no caderno.", "wrong": "As alternativas A, B, D e E trocam pelo menos uma das características.", "basis": "NBC TSP Estrutura Conceitual / MCASP, características qualitativas da informação contábil.", "trap": "Observe que a mesma característica pode aparecer em mais de uma assertiva; IV também descreve representação fidedigna."}$qq$::jsonb, $qq$caps. 1 a 4) 211) De acordo com a NBC TSP - Estrutura Conceitual para Elaboração e Divulgação de Informação Contábil de Propósito Geral pelas Entidades do Setor Público, avalie as afirmativas apresentadas a seguir sobre as características qualitativas da informação incluídas no Relatório Contábil de Propósito Geral das Entidades do Setor Público  w w .teccon…$qq$),
($qq$2158740$qq$, 308, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont (Pref Itapoá)/Pref Itapoá/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 212) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, considere as assertivas: I - As escriturações contábeis do setor público devem ser elaboradas com base no regime de competência. II - O objetivo principal da maioria das entidades do setor público é prestar serviços à sociedade, em vez de obter lucros e gerar retorno financeiro aos investidores. Está CORRETO o que se afirma em:$qq$, $qq$[["A", "I e II são verdadeiras."], ["B", "Apenas a I é verdadeira."], ["C", "I e II são falsas."], ["D", "Apenas a II é verdadeira."], ["E", "Nenhuma das alternativas."]]$qq$::jsonb, $qq$A$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Regime de competência e objetivo das entidades públicas.", "rule": "A contabilidade do setor público utiliza o regime de competência para os registros patrimoniais, e o objetivo principal da maioria das entidades públicas é prestar serviços à sociedade, não gerar lucro para investidores.", "steps": ["I: regime de competência → verdadeira.", "II: prestação de serviços à sociedade como objetivo principal → verdadeira.", "Logo, I e II são verdadeiras."], "calc": "Não há cálculo.", "correct": "A — I e II são verdadeiras.", "wrong": "B e D eliminam uma das assertivas verdadeiras; C considera ambas falsas; E não se aplica.", "basis": "NBC TSP Estrutura Conceitual.", "trap": "Não confundir objetivo público com objetivo típico de entidade empresarial: resultado financeiro é relevante, mas não resume o desempenho do setor público."}$qq$::jsonb, $qq$caps. 1 a 4) 212) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, considere as assertivas: I - As escriturações contábeis do setor público devem ser elaboradas com base no regime de competência. II - O objetivo principal da maioria das entidades do setor público é prestar serviços à sociedade, em vez d…$qq$),
($qq$2158741$qq$, 309, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont (Pref Itapoá)/Pref Itapoá/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 213) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale abaixo a alternativa que corresponde ao texto contido no item 1.4:$qq$, $qq$[["A", "Nenhuma das alternativas."], ["B", "Os RCPGs são os componentes centrais da transparência da informação contábil dos governos e de outras entidades do setor público, aprimorando-a e favorecendo-a. Os RCPGs são relatórios matemáticos elaborados para atender às necessidades dos usuários em geral, não tendo o propósito de atender à finalidades ou necessidades específicas de determinados grupos de usuários."], ["C", "Os RCPGs são os componentes centrais da transparência da informação contábil dos governos e de outras entidades do setor público, aprimorando-a e favorecendo-a. Os RCPGs são relatórios físicos elaborados para atender às necessidades dos usuários em geral, não tendo o propósito de atender à finalidades ou necessidades específicas de determinados grupos de usuários."], ["D", "Os RCPGs são os componentes centrais da transparência da informação contábil dos governos e de outras entidades do setor público, aprimorando-a e favorecendo-a. Os RCPGs são relatórios químicos elaborados para atender às necessidades dos usuários em geral, não tendo o propósito de atender à finalidades ou necessidades específicas de determinados grupos de usuários."], ["E", "Os RCPGs são os componentes centrais da transparência da informação contábil dos governos e de outras entidades do setor público, aprimorando-a e favorecendo-a. Os RCPGs são relatórios contábeis elaborados para atender às necessidades dos usuários em geral, não tendo o propósito de atender à finalidades ou necessidades específicas de determinados grupos de usuários."]]$qq$::jsonb, $qq$E$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Texto do item 1.4 da NBC TSP Estrutura Conceitual sobre RCPGs.", "rule": "O item citado caracteriza os RCPGs como componentes centrais da transparência da informação contábil e como relatórios contábeis destinados a atender às necessidades dos usuários em geral, sem finalidade específica para determinado grupo.", "steps": ["Comparar “relatórios matemáticos”, “físicos”, “químicos” e “contábeis”.", "A expressão correta é “relatórios contábeis”.", "A alternativa E reproduz a formulação registrada no material."], "calc": "Não há cálculo.", "correct": "E.", "wrong": "B, C e D alteram artificialmente o termo “contábeis”; A é desnecessária porque há alternativa compatível.", "basis": "NBC TSP Estrutura Conceitual, item 1.4, conforme texto cobrado no caderno.", "trap": "Questão de literalidade: uma única palavra alterada invalida a alternativa."}$qq$::jsonb, $qq$caps. 1 a 4) 213) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale abaixo a alternativa que corresponde ao texto contido no item 1.4:$qq$),
($qq$2158742$qq$, 310, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont (Pref Itapoá)/Pref Itapoá/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 214) Em relação a Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale abaixo a alternativa que corresponde ao texto contido no item 1.8B:$qq$, $qq$[["A", "As empresas estatais dependentes são empresas controladas que recebem do ente controlador recursos financeiros para pagamento de despesas pessoais, despesas de custeio em geral ou despesas de capital, excluídos, no último caso, aqueles provenientes de aumento de participação acionária.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                              4/57"], ["B", "As empresas estatais dependentes são empresas controladas que recebem do ente controlador recursos financeiros para pagamento de despesas com pessoal, despesas de custeio em geral ou despesas de capital, excluídos, no último caso, aqueles provenientes de diminuição de participação acionária."], ["C", "Nenhuma das alternativas."], ["D", "As empresas estatais dependentes são empresas controladas que recebem do ente controlador recursos financeiros para pagamento de despesas com pessoal, despesas de custeio em geral ou despesas de capital, excluídos, no último caso, aqueles provenientes de aumento de participação acionária."], ["E", "As empresas estatais dependentes são empresas descontroladas que recebem do ente controlador recursos financeiros para pagamento de despesas com pessoal, despesas de custeio em geral ou despesas de capital, excluídos, no último caso, aqueles provenientes de aumento de participação acionária."]]$qq$::jsonb, $qq$D$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Definição de empresa estatal dependente na NBC TSP Estrutura Conceitual.", "rule": "Empresa estatal dependente é empresa controlada que recebe do ente controlador recursos financeiros para pagamento de despesas com pessoal, custeio em geral ou despesas de capital, excluídos, no último caso, os recursos provenientes de aumento de participação acionária.", "steps": ["Identificar “empresa controlada”.", "Identificar recursos do ente controlador para pessoal, custeio ou capital.", "Na despesa de capital, excluir recursos provenientes de aumento de participação acionária."], "calc": "Não há cálculo.", "correct": "D.", "wrong": "A troca “pessoal” por “pessoais”; B troca aumento por diminuição de participação; C nega a existência da definição; E troca controlada por descontrolada.", "basis": "NBC TSP Estrutura Conceitual, item 1.8B, conforme texto cobrado.", "trap": "A expressão-chave é “aumento de participação acionária”; a banca altera uma única palavra para mudar o sentido."}$qq$::jsonb, $qq$caps. 1 a 4) 214) Em relação a Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale abaixo a alternativa que corresponde ao texto contido no item 1.8B:$qq$),
($qq$2158743$qq$, 311, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont (Pref Itapoá)/Pref Itapoá/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 215) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale a alternativa abaixo que corresponde ao texto contido no item 2.22:$qq$, $qq$[["A", "O objetivo principal dos governos e da maioria das entidades do setor público é prestar os serviços necessários para a sociedade. Consequentemente, o desempenho dos governos e da maioria das entidades do setor público não está total ou adequadamente refletido em qualquer medida de resultados financeiros. Portanto, os resultados financeiros não necessitam ser avaliados no contexto dos resultados da prestação de serviços à sociedade."], ["B", "O objetivo principal dos governos e da maioria das entidades do setor público é prestar os serviços necessários para a sociedade. Consequentemente, o desempenho dos governos e da maioria das entidades do setor público está total ou adequadamente refletido em qualquer medida de resultados financeiros."], ["C", "O objetivo principal dos governos e da maioria das entidades do setor público é melhorar as contas do governo. Consequentemente, o desempenho dos governos e da maioria das entidades do setor público não está total ou adequadamente refletido em qualquer medida de resultados financeiros. Portanto, os resultados financeiros necessitam ser avaliados no contexto dos resultados da prestação de serviços à sociedade."], ["D", "Nenhuma das alternativas."], ["E", "O objetivo principal dos governos e da maioria das entidades do setor público é prestar os serviços necessários para a sociedade. Consequentemente, o desempenho dos governos e da maioria das entidades do setor público não está total ou adequadamente refletido em qualquer medida de resultados financeiros. Portanto, os resultados financeiros necessitam ser avaliados no contexto dos resultados da prestação de serviços à sociedade."]]$qq$::jsonb, $qq$E$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Objetivo principal do governo e avaliação do desempenho público.", "rule": "O objetivo principal dos governos e da maioria das entidades do setor público é prestar serviços à sociedade. Seu desempenho não é total ou adequadamente refletido por uma única medida de resultados financeiros; por isso, resultados financeiros devem ser avaliados no contexto dos resultados da prestação de serviços.", "steps": ["Identificar o objetivo: prestar serviços à sociedade.", "Reconhecer que resultados financeiros não capturam integralmente o desempenho público.", "Concluir que os resultados financeiros devem ser analisados junto dos resultados da prestação de serviços."], "calc": "Não há cálculo.", "correct": "E.", "wrong": "A erra ao dizer que resultados financeiros não precisam ser contextualizados; B diz que o desempenho é adequadamente refletido por medidas financeiras; C troca o objetivo público por “melhorar as contas”; D é desnecessária.", "basis": "NBC TSP Estrutura Conceitual, item 2.22, conforme texto cobrado.", "trap": "Não concluir que resultado financeiro é irrelevante; o ponto é que ele não é suficiente, sozinho, para medir o desempenho público."}$qq$::jsonb, $qq$caps. 1 a 4) 215) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale a alternativa abaixo que corresponde ao texto contido no item 2.22:$qq$),
($qq$2158745$qq$, 312, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont (Pref Itapoá)/Pref Itapoá/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 216) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale abaixo qual alternativa corresponde ao texto contido no item 2.23:$qq$, $qq$[["A", "Nenhuma das alternativas."], ["B", "Em todos os casos, as mensurações quantitativas dos produtos e resultados das atividades de prestação de serviços da entidade durante o exercício fornecem informações relevantes sobre o cumprimento dos objetivos da prestação de serviços - por exemplo, a informação sobre o custo, o volume e a frequência da prestação de serviços e a relação dos serviços prestados com a quantidade de recursos da entidade. Em todos os casos, é necessário comunicar a realização dos objetivos da prestação de serviços por meio da explicação da qualidade de determinados serviços prestados ou do resultado de determinados programas."], ["C", "Em alguns casos, as mensurações quantitativas dos produtos e resultados das atividades de prestação de serviços da entidade durante o exercício fornecem informações relevantes sobre o cumprimento dos objetivos da prestação de serviços - por exemplo, a informação sobre o custo, o volume e a frequência da prestação de serviços e a relação dos serviços prestados com a quantidade de recursos da entidade. Em outros casos, pode ser necessário comunicar a realização dos objetivos da prestação de serviços por meio da explicação da qualidade de determinados serviços prestados ou do resultado de determinados programas."], ["D", "Em alguns casos, as mensurações quantitativas dos produtos e resultados das atividades de prestação de serviços da entidade durante o exercício não fornecem informações relevantes sobre o cumprimento dos objetivos da prestação de serviços - por exemplo, a informação sobre o custo, o volume e a frequência da prestação de serviços e a relação dos serviços prestados com a quantidade de recursos da entidade. Em outros casos, pode ser necessário comunicar a realização dos objetivos da prestação de serviços por meio da explicação da qualidade de determinados serviços prestados ou do resultado de determinados programas."], ["E", "Em alguns casos, as mensurações quantitativas dos produtos e resultados das atividades de prestação de serviços da entidade durante o exercício fornecem informações relevantes sobre o cumprimento dos objetivos da prestação de serviços - por exemplo, a informação sobre o custo, o volume e a frequência da prestação de serviços e a relação dos serviços prestados com a quantidade de recursos da entidade. Em todos os casos, é necessário comunicar a realização dos objetivos da prestação de serviços por meio da explicação da qualidade de determinados serviços prestados ou do resultado de determinados programas."]]$qq$::jsonb, $qq$C$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Mensurações quantitativas de produtos e resultados da prestação de serviços.", "rule": "O item 2.23 reconhece que, em alguns casos, mensurações quantitativas fornecem informações relevantes; em outros, pode ser necessário explicar qualidade de serviços ou resultados de programas.", "steps": ["Localizar a expressão “em alguns casos”.", "Verificar que o texto prossegue com “em outros casos”.", "A alternativa C mantém essa estrutura e o conteúdo correspondente."], "calc": "Não há cálculo.", "correct": "C.", "wrong": "B usa “em todos os casos” nas duas situações; D nega a relevância das mensurações; E usa “em todos os casos” para a segunda parte; A não se aplica.", "basis": "NBC TSP Estrutura Conceitual, item 2.23, conforme texto cobrado.", "trap": "Questão de literalidade: “alguns casos” versus “todos os casos” muda completamente a proposição."}$qq$::jsonb, $qq$caps. 1 a 4) 216) Em relação à Norma Brasileira de Contabilidade, NBC TSP Estrutura Conceitual, de 23 de setembro de 2016, assinale abaixo qual alternativa corresponde ao texto contido no item 2.23:$qq$),
($qq$2413232$qq$, 313, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Ag (CM Chavantes)/CM Chavantes/Administrativo/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 217) A NBC T 16.1 estabelece a conceituação, o objeto e o campo de aplicação da Contabilidade Aplicada ao Setor Público, além de tratar sobre Unidade Contábil, a qual pode ser classificada em alguns tipos. Nesse sentido, assinale a alternativa que trate sobre uma das classificações que representa a parcela do patrimônio de Unidade Contábil Originária:$qq$, $qq$[["A", "Consolidada."], ["B", "Unificada."], ["C", "Descentralizada."], ["D", "Centralizada."], ["E", "Originária."]]$qq$::jsonb, $qq$C$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Classificação da Unidade Contábil que representa parcela do patrimônio de Unidade Contábil Originária.", "rule": "Na terminologia da antiga NBC T 16.1, a unidade contábil descentralizada representa parcela do patrimônio de uma unidade contábil originária.", "steps": ["Identificar que a pergunta fala em “parcela do patrimônio”.", "Essa parcela pertence a uma unidade contábil originária.", "A classificação correspondente é descentralizada."], "calc": "Não há cálculo.", "correct": "C — Descentralizada.", "wrong": "Originária é a unidade-base; consolidada e unificada são outras formas de agregação; “centralizada” não é a classificação pedida.", "basis": "NBC T 16.1, conforme a terminologia cobrada na questão.", "trap": "Não confundir “descentralizada” com “unificada”: a primeira trata de parcela do patrimônio de unidade originária."}$qq$::jsonb, $qq$caps. 1 a 4) 217) A NBC T 16.1 estabelece a conceituação, o objeto e o campo de aplicação da Contabilidade Aplicada ao Setor Público, além de tratar sobre Unidade Contábil, a qual pode ser classificada em alguns tipos. Nesse sentido, assinale a alternativa que trate sobre uma das classificações que representa a parcela do patrimônio de Unidade Contábil Origi…$qq$),
($qq$3023784$qq$, 314, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Ana Cont (CRJ)/CRJ/2022$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4)  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                            5/57 218) A contabilidade pública oferece suporte para as atividades da administração pública e é responsável pelas atividades de registro, controle e geração de demonstrativos orçamentários, dando apoio à Secretaria da Fazenda e o Controle do Patrimônio público. Em referência às normas e abrangência da Contabilidade Pública, NÃO são exigíveis para as seguintes entidades:$qq$, $qq$[["A", "Fundos Públicos."], ["B", "Administração Direta."], ["C", "Autarquias."], ["D", "Fundações Públicas."], ["E", "Estatais Independentes."]]$qq$::jsonb, $qq$E$qq$, 2022, null, 1078, $qq$A$qq$, $qq${"what": "Entidades não abrangidas pela exigibilidade indicada na questão.", "rule": "No recorte tradicional da Contabilidade Aplicada ao Setor Público, estatais independentes não se submetem ao mesmo regime contábil público das entidades dependentes abrangidas pela CASP.", "steps": ["Identificar as opções: fundos públicos, administração direta, autarquias, fundações públicas e estatais independentes.", "As quatro primeiras integram o campo típico da contabilidade pública.", "A exceção cobrada é a empresa estatal independente."], "calc": "Não há cálculo.", "correct": "E — Estatais Independentes.", "wrong": "A, B, C e D são entidades abrangidas pelo campo de aplicação indicado na questão.", "basis": "NBC T 16.1/MCASP e legislação aplicável ao campo da CASP, conforme o material da questão.", "trap": "Não confundir estatal independente com estatal dependente; esta última é tratada de forma distinta e integra o universo relevante da CASP."}$qq$::jsonb, $qq$caps. 1 a 4)  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                            5/57 218) A contabilidade pública oferece suporte para as atividades da administração pública e é responsável pelas atividades de registro, controle e geração de demonstrativos orçamentários, d…$qq$),
($qq$1741232$qq$, 315, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (CM Castro)/CM Castro/2021$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Nos municípios, a despesa total com pessoal em cada período de apuração, conforme estabelece a Lei Complementar N.º 101/2000, NÃO poderá exceder os percentuais da receita corrente líquida, em:$qq$, $qq$[["A", "50% (cinquenta por cento)."], ["B", "30% (trinta por cento)."], ["C", "70% (setenta por cento)."], ["D", "60% (sessenta por cento)."], ["E", "40% (quarenta por cento)."]]$qq$::jsonb, $qq$D$qq$, 2021, 156, 1078, $qq$A$qq$, $qq${"what": "Limite global de pessoal nos Municípios.", "rule": "O limite da despesa total com pessoal para Municípios é 60% da Receita Corrente Líquida.", "steps": ["Identificar Município.", "Aplicar art. 19, III.", "Selecionar 60%."], "calc": "60% da RCL.", "correct": "D — 60%.", "wrong": "50%, 30%, 70% e 40% não correspondem ao limite global municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Questão repetitiva da FAFIPA: grave o trio municipal 60% global, 54% Executivo, 6% Legislativo."}$qq$::jsonb, $qq$Nos municípios, a despesa total com pessoal em cada período de apuração, conforme estabelece a Lei Complementar N.º 101/2000, NÃO poderá exceder os percentuais da receita corrente líquida, em:$qq$),
($qq$1973398$qq$, 316, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (CM Marumbi)/CM Marumbi/2020$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Sobre a despesa total com pessoal, a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal) prevê que os municípios, em cada período de apuração, não podem exceder o valor das despesas com pessoal sobre a receita corrente líquida em:$qq$, $qq$[["A", "40%."], ["B", "60%."], ["C", "70%."], ["D", "50%."]]$qq$::jsonb, $qq$B$qq$, 2020, 157, 1078, $qq$A$qq$, $qq${"what": "Limite global de pessoal nos Municípios.", "rule": "A despesa total com pessoal dos Municípios não pode exceder 60% da RCL.", "steps": ["Ente: Município.", "Limite global: 60%.", "Alternativa correspondente: B."], "calc": "60% da RCL.", "correct": "B — 60%.", "wrong": "40%, 70% e 50% não são o limite municipal.", "basis": "Lei Complementar nº 101/2000, art. 19, III.", "trap": "Memorizar o limite por ente evita confusão com os limites da União e dos Estados."}$qq$::jsonb, $qq$Sobre a despesa total com pessoal, a Lei Complementar nº 101/2000 (Lei de Responsabilidade Fiscal) prevê que os municípios, em cada período de apuração, não podem exceder o valor das despesas com pessoal sobre a receita corrente líquida em:$qq$),
($qq$2164727$qq$, 317, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Proc (Campo Largo)/Pref Campo Largo/2020$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$A Lei Complementar N.º 101/2000 dispõe que “entende-se como despesa total com pessoal: o somatório dos gastos do ente da Federação com os ativos, os inativos e os pensionistas, relativos a mandatos eletivos, cargos, funções ou empregos, civis, militares e de membros de Poder, com quaisquer espécies remuneratórias, tais como vencimentos e vantagens, fixas e variáveis, subsídios, proventos da aposentadoria, reformas e pensões, inclusive adicionais, gratificações, horas extras e vantagens pessoais de qualquer natureza, bem como encargos sociais e contribuições recolhidas pelo ente às entidades de previdência”. Desta forma, sobre os limites dessas despesas, nos termos da referida norma, assinale a alternativa CORRETA:$qq$, $qq$[["A", "A despesa total com pessoal em cada período de apuração não poderá exceder os percentuais de 35% para a União, 45% para os Estados e 45% para os municípios, da receita corrente líquida."], ["B", "A repartição dos limites globais não poderá exceder, na esfera municipal, 54% (cinquenta e quatro por cento) para o Executivo."], ["C", "A repartição dos limites globais não poderá exceder, na esfera estadual, 3% (três por cento) para o Ministério Público dos Estados."], ["D", "A repartição dos limites globais não poderá exceder, na esfera federal, 5% (cinco por cento) para o Judiciário."], ["E", "Para a verificação dos limites com despesa total com pessoal, deverão ser computadas as despesas com inativos, ainda que por intermédio de fundo específico, custeadas por recursos provenientes das demais receitas diretamente arrecadadas por fundo vinculado a tal finalidade, inclusive o produto da alienação de bens, direitos e ativos, bem como seu superávit financeiro."]]$qq$::jsonb, $qq$B$qq$, 2020, 158, 1078, $qq$A$qq$, $qq${"what": "Repartição dos limites globais e exclusões na apuração da despesa com pessoal.", "rule": "No Município, o limite global é 60%, repartido em 54% para o Executivo e 6% para o Legislativo. A LRF também prevê exclusões específicas na apuração, inclusive determinadas despesas com inativos custeadas por recursos próprios vinculados nas condições legais.", "steps": ["A alternativa B afirma corretamente que o Executivo municipal não pode ultrapassar 54%.", "A alternativa A traz percentuais globais incorretos.", "C e D trazem repartições incompatíveis com a LRF.", "E erra ao dizer que devem ser computadas determinadas despesas com inativos que a própria LRF manda excluir quando atendidas as condições."], "calc": "Limite Executivo municipal = 54% da RCL; Legislativo = 6% da RCL.", "correct": "B.", "wrong": "A, C e D apresentam percentuais incorretos; E contraria a regra de exclusão do art. 19, §1º, VI.", "basis": "Lei Complementar nº 101/2000, arts. 19, §1º, VI, e 20, III.", "trap": "Além dos percentuais, a FAFIPA pode cobrar as parcelas que não entram no cálculo da despesa total com pessoal."}$qq$::jsonb, $qq$A Lei Complementar N.º 101/2000 dispõe que “entende-se como despesa total com pessoal: o somatório dos gastos do ente da Federação com os ativos, os inativos e os pensionistas, relativos a mandatos eletivos, cargos, funções ou empregos, civis, militares e de membros de Poder, com quaisquer espécies remuneratórias, tais como vencimentos e vantagens, fixas e v…$qq$),
($qq$2165661$qq$, 318, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (Pref C Largo)/Pref Campo Largo/2020$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Nos municípios, a despesa total com pessoal em cada período de apuração, conforme estabelece a Lei Complementar Nº 101/2000, não poderá exceder à 60% (sessenta por cento) da receita corrente líquida nos municípios. Sob esse aspecto, a repartição dos limites globais não poderá exceder os seguintes percentuais na esfera municipal: I. _________________ para o Legislativo, incluído o Tribunal de Contas do Município, quando houver. II. _________________ para o Executivo. Assinale a alternativa que preencha CORRETAMENTE as lacunas:$qq$, $qq$[["A", "I – 6% (seis por cento); II – 54% (cinquenta e quatro por cento)."], ["B", "I – 54% (cinquenta e quatro por cento); II – 6% (seis por cento)."], ["C", "I – 56% (cinquenta e seis por cento); II – 4% (quatro por cento)."], ["D", "I – 4% (quatro por cento); II – 56% (cinquenta e seis por cento)."], ["E", "I – 10% (dez por cento); II – 50% (cinquenta por cento)."]]$qq$::jsonb, $qq$A$qq$, 2020, 159, 1078, $qq$A$qq$, $qq${"what": "Repartição do limite municipal de 60% entre Legislativo e Executivo.", "rule": "O limite global municipal de 60% da RCL é repartido em 6% para o Legislativo, incluído o Tribunal de Contas do Município quando houver, e 54% para o Executivo.", "steps": ["Limite global municipal = 60%.", "Legislativo = 6%.", "Executivo = 54%.", "6% + 54% = 60%."], "calc": "6% + 54% = 60% da RCL.", "correct": "A — I 6%; II 54%.", "wrong": "B inverte os percentuais; C e D usam 56/4 ou 4/56; E não corresponde à repartição legal.", "basis": "Lei Complementar nº 101/2000, art. 20, III.", "trap": "A inversão 54%/6% é uma pegadinha clássica."}$qq$::jsonb, $qq$Nos municípios, a despesa total com pessoal em cada período de apuração, conforme estabelece a Lei Complementar Nº 101/2000, não poderá exceder à 60% (sessenta por cento) da receita corrente líquida nos municípios. Sob esse aspecto, a repartição dos limites globais não poderá exceder os seguintes percentuais na esfera municipal: I. _________________ para o L…$qq$),
($qq$916313$qq$, 319, $qq$AFO, Direito Financeiro e Contabilidade Pública - Despesas com Pessoal e Seguridade Social (arts. 18 a 24 da LRF)$qq$, $qq$FAFIPA - Cont (CM 2 Vizinhos)/CM 2 Vizinhos/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$(Lei 101/2000) A despesa total com pessoal, em cada período de apuração e, em cada ente da Federação, não poderá exceder os percentuais da receita corrente líquida, nos percentuais de:$qq$, $qq$[["A", "União 55%, Estados 60%, Municípios 50%."], ["B", "União 60%, Estados 65%, Municípios 55%."], ["C", "União 50%, Estados 60%, Municípios 60%."], ["D", "União 60%, Estados 55%, Municípios 60%."], ["E", "União 45%, Estados 50%, Municípios 60%."]]$qq$::jsonb, $qq$C$qq$, 2019, 160, 1078, $qq$A$qq$, $qq${"what": "Limites globais de despesa com pessoal por ente.", "rule": "A LRF estabelece: União 50% da RCL; Estados 60%; Municípios 60%.", "steps": ["União → 50%.", "Estados → 60%.", "Municípios → 60%.", "Comparar com as alternativas."], "calc": "União 50% + Estados 60% + Municípios 60%.", "correct": "C.", "wrong": "As demais alternativas alteram pelo menos um dos três percentuais.", "basis": "Lei Complementar nº 101/2000, art. 19, I a III.", "trap": "Decore por ente: 50–60–60. Não confundir esses limites globais com a repartição interna entre Poderes."}$qq$::jsonb, $qq$(Lei 101/2000) A despesa total com pessoal, em cada período de apuração e, em cada ente da Federação, não poderá exceder os percentuais da receita corrente líquida, nos percentuais de:$qq$),
($qq$1336830$qq$, 320, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont Jr (FOZTRANS)/FOZTRANS/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 219) A Estrutura Conceitual Aplicável ao Setor Público (NBC TSP) segrega o escopo de aplicação das normas de Contabilidade Aplicada ao Setor Público em obrigatório e facultativo. Das entidades a seguir, as que se enquadram no escopo de aplicação facultativo são:$qq$, $qq$[["A", "Autarquias."], ["B", "Consórcios públicos."], ["C", "Empresas estatais dependentes."], ["D", "Fundações públicas."], ["E", "Organizações da sociedade civil de interesse público."]]$qq$::jsonb, $qq$E$qq$, 2019, null, 1078, $qq$A$qq$, $qq${"what": "Escopo facultativo da NBC TSP Estrutura Conceitual.", "rule": "Na classificação cobrada pela questão, organizações da sociedade civil de interesse público (OSCIPs) enquadram-se no escopo facultativo; autarquias, consórcios públicos, estatais dependentes e fundações públicas integram o escopo obrigatório indicado no material.", "steps": ["Identificar as cinco categorias apresentadas.", "Separar entidades típicas do setor público das organizações privadas que podem atuar em parceria com o poder público.", "A alternativa correspondente ao escopo facultativo é OSCIP."], "calc": "Não há cálculo.", "correct": "E — Organizações da sociedade civil de interesse público.", "wrong": "A, B, C e D correspondem às entidades apontadas como de aplicação obrigatória no recorte da questão.", "basis": "NBC TSP Estrutura Conceitual, conforme classificação cobrada no caderno.", "trap": "Não confundir “atuar em parceria com o poder público” com pertencer automaticamente ao escopo obrigatório das normas."}$qq$::jsonb, $qq$caps. 1 a 4) 219) A Estrutura Conceitual Aplicável ao Setor Público (NBC TSP) segrega o escopo de aplicação das normas de Contabilidade Aplicada ao Setor Público em obrigatório e facultativo. Das entidades a seguir, as que se enquadram no escopo de aplicação facultativo são:$qq$),
($qq$1336831$qq$, 321, $qq$AFO, Direito Financeiro e Contabilidade Pública - Conceitos, Objeto, Objetivos e Campo de Aplicação (Estrutura Conceitual - Prefácio e$qq$, $qq$FAFIPA - Cont Jr (FOZTRANS)/FOZTRANS/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$caps. 1 a 4) 220) O objetivo da Contabilidade Pública é o de fornecer aos gestores informações para subsidiar as tomadas de decisões, aos órgãos de controle interno e externo para o cumprimento da legislação e às instituições governamentais e particulares informações estatísticas e outras de interesse dessas instituições. Neste contexto, o campo de aplicação da contabilidade pública abrangerá:$qq$, $qq$[["A", "Todos os órgãos da administração pública."], ["B", "Apenas os órgãos da administração indireta."], ["C", "Somente as autarquias e fundações."], ["D", "Todos os órgãos de administração direta."], ["E", "Autarquias, fundações e todos os órgãos da administração indireta."]]$qq$::jsonb, $qq$D$qq$, 2019, null, 1078, $qq$A$qq$, $qq${"what": "Campo de aplicação da contabilidade pública no recorte da questão.", "rule": "A questão considera como abrangidos todos os órgãos da administração direta.", "steps": ["Identificar a alternativa que corresponde diretamente à administração direta.", "A opção D afirma “todos os órgãos de administração direta”.", "Essa é a alternativa registrada como correta no caderno."], "calc": "Não há cálculo.", "correct": "D — Todos os órgãos de administração direta.", "wrong": "B, C e E restringem ou ampliam o campo de modo diferente do enunciado; A generaliza para todos os órgãos da administração pública.", "basis": "Normas de Contabilidade Aplicada ao Setor Público, conforme o enquadramento adotado na questão.", "trap": "Questão de campo de aplicação: leia com atenção “todos”, “apenas” e “somente”."}$qq$::jsonb, $qq$caps. 1 a 4) 220) O objetivo da Contabilidade Pública é o de fornecer aos gestores informações para subsidiar as tomadas de decisões, aos órgãos de controle interno